@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=618  cases=17
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, tuning.stepToMidi, cm:set, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-112
  @fn seedItems(h, takes)  @ 128-133
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 135-144

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 148-156
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 159-168
  @case 'focusState before any render returns both bits false'  [harness]  @ 171-178
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 184-197
  @case 'newTakeBelow + duplicateUnpooledBelow mint a parked slot on scratch and select it'  [harness]  @ 201-222
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 226-249
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 256-273
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 277-300
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 304-327
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 331-366
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 370-386
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 392-447
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 455-484
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 490-533
  @case 'empty grid shows the single no-takes message'  [harness]  @ 539-553
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 560-592
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 596-616

